SELECT ((SELECT COUNT(*) FROM character_data WHERE name = 'Claudewright' AND account_id = 86 AND race = 1 AND gender = 0 AND class = 12) = 1 AND (SELECT COUNT(*) FROM character_bind WHERE id IN (SELECT id FROM character_data WHERE name = 'Claudewright')) = 5 AND (SELECT COUNT(*) FROM character_languages WHERE id IN (SELECT id FROM character_data WHERE name = 'Claudewright') AND lang_id = 0 AND value = 100) = 1) AS applied;
